package ama.transcript;
import ama.meeting.WorkspaceReadBudget;import java.time.*;import java.util.*;import java.sql.*;import javax.sql.DataSource;import org.springframework.jdbc.core.JdbcTemplate;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
/** Actual JDBC relation/lock-order protocol with metadata doubles; no owner gate/MySQL qualification. */
class Task12WorkspaceTaskRelationsTest {
 static final String M="00000000-0000-4000-8000-000000000001",T="00000000-0000-4000-8000-000000000002",I="00000000-0000-4000-8000-000000000003",B="00000000-0000-4000-8000-000000000004",C="00000000-0000-4000-8000-000000000005";
 Map<String,Map<String,Object>> rows;List<String> sql;JdbcTemplate jdbc;
 static Map<String,Object> row(Object...args){var r=new LinkedHashMap<String,Object>();for(int i=0;i<args.length;i+=2)r.put((String)args[i],args[i+1]);return r;}
 @BeforeEach void setup()throws Exception{rows=new HashMap<>();sql=new ArrayList<>();var ds=mock(DataSource.class);var c=mock(Connection.class);when(ds.getConnection()).thenReturn(c);when(c.prepareStatement(anyString())).thenAnswer(call->{String q=call.getArgument(0);sql.add(q);var st=mock(PreparedStatement.class);when(st.getConnection()).thenReturn(c);when(st.executeQuery()).thenAnswer(x->{String table=q.split(" FROM ")[1].split(" ")[0];var value=rows.get(table);var rs=mock(ResultSet.class);when(rs.next()).thenReturn(value!=null,false);when(rs.getObject(anyString())).thenAnswer(a->value.get(a.getArgument(0)));return rs;});return st;});jdbc=new JdbcTemplate(ds);
 rows.put("transcription_input",row("id",I,"meeting_id",M,"batch_id",B,"kind","IMPORT","material_mode","EMPTY","material_snapshot_id",null,"source_revision_id",null,"model_config_version",null,"prompt_version",null,"parser_version","v1","manifest_schema_version",1L,"input_fingerprint","b".repeat(64),"base_revision",7L,"cancel_epoch",0L));rows.put("input_batch",row("id",B,"meeting_id",M,"kind","TRANSCRIPT","base_revision",7L));rows.put("input_batch_fingerprint_profile",row("batch_id",B,"profile","ama.input-batch.v1"));
 }
 WorkspaceTaskScan.Metadata task(String type){boolean publish=type.equals("KNOWLEDGE_PUBLISH_V1");return WorkspaceTaskScan.metadata(T,type,publish?"KNOWLEDGE_PUBLISH":"TRANSCRIPT_IMPORT","MEETING",M,"a".repeat(64),publish?"PUBLICATION":"TRANSCRIPTION_INPUT",I,"b".repeat(64),7,0,0,3,"RUNNING",1,LocalDateTime.of(2026,10,27,0,0));}
 @Test void importLocksDeclaredParentRowsAndNeverReadsManifest(){var proof=new WorkspaceTaskRelations(jdbc,new WorkspaceReadBudget());proof.capture(List.of(task("TRANSCRIPT_IMPORT_V1")));proof.lockAndCompare();assertEquals(List.of("transcription_input","input_batch","input_batch_fingerprint_profile"),sql.stream().filter(q->q.endsWith("FOR UPDATE")).map(q->q.split(" FROM ")[1].split(" ")[0]).toList());assertTrue(sql.stream().noneMatch(q->q.contains("SELECT *")||q.contains("config_manifest")||q.contains("request_manifest")));}
 @Test void inputBelongingToAnotherMeetingOrChangedAfterCaptureIsRejected(){rows.get("input_batch").put("meeting_id",C);assertThrows(WorkspaceReadBudget.Unavailable.class,()->new WorkspaceTaskRelations(jdbc,new WorkspaceReadBudget()).capture(List.of(task("TRANSCRIPT_IMPORT_V1"))));rows.get("input_batch").put("meeting_id",M);var proof=new WorkspaceTaskRelations(jdbc,new WorkspaceReadBudget());proof.capture(List.of(task("TRANSCRIPT_IMPORT_V1")));rows.get("transcription_input").put("parser_version","v2");assertThrows(WorkspaceReadBudget.Unavailable.class,proof::lockAndCompare);}
 @Test void publicationRequiresOriginalSubmissionAndOriginalFinalEvenWhenCurrentFinalDiffers(){var task=task("KNOWLEDGE_PUBLISH_V1");rows.put("publication",row("id",I,"meeting_id",M));rows.put("final_confirmation",row("id",C,"meeting_id",M,"meeting_revision",7L));assertThrows(WorkspaceReadBudget.Unavailable.class,()->new WorkspaceTaskRelations(jdbc,new WorkspaceReadBudget()).capture(List.of(task)));rows.put("publication_submission",row("task_id",T,"publication_id",I,"confirmation_id",C,"logical_request_hash","b".repeat(64),"submission_no",1L,"business_key",I+":"+C));var proof=new WorkspaceTaskRelations(jdbc,new WorkspaceReadBudget());proof.capture(List.of(task));proof.lockAndCompare();rows.get("publication_submission").put("logical_request_hash","c".repeat(64));assertThrows(WorkspaceReadBudget.Unavailable.class,()->new WorkspaceTaskRelations(jdbc,new WorkspaceReadBudget()).capture(List.of(task)));}
 @Test void budgetExhaustionStopsBeforeFirstParentQuery(){var limits=new WorkspaceReadBudget.Limits(1,1,1,1,1,1,Duration.ofSeconds(5));assertThrows(WorkspaceReadBudget.Unavailable.class,()->new WorkspaceTaskRelations(jdbc,new WorkspaceReadBudget(limits,()->false)).capture(List.of(task("TRANSCRIPT_IMPORT_V1"))));assertTrue(sql.isEmpty());}

 @Test void relationNavigationDoesNotInventAnEqualityBetweenHistoricalFinalAndTaskCounters(){rows.put("publication",row("id",I,"meeting_id",M));rows.put("final_confirmation",row("id",C,"meeting_id",M,"meeting_revision",6L));rows.put("publication_submission",row("task_id",T,"publication_id",I,"confirmation_id",C,"logical_request_hash","b".repeat(64),"submission_no",1L,"business_key",I+":"+C));assertDoesNotThrow(()->new WorkspaceTaskRelations(jdbc,new WorkspaceReadBudget()).capture(List.of(task("KNOWLEDGE_PUBLISH_V1"))));}
 @Test void generationRequiresWorkingAndSameMeetingParents(){var task=WorkspaceTaskScan.metadata(T,"MINUTES_GENERATE_V1","MINUTES_GENERATE","MEETING",M,"a".repeat(64),"GENERATION_INPUT",I,"b".repeat(64),7,0,0,3,"SUCCEEDED",1,LocalDateTime.of(2026,10,27,0,0));rows.put("generation_input",row("id",I,"meeting_id",M,"transcript_confirmation_id",C,"template_revision_id",B,"exclusion_revision_id",B,"base_revision",7L,"input_fingerprint","b".repeat(64),"scope","FULL","target_element_id",null,"material_snapshot_id",null));rows.put("transcript_confirmation",row("id",C,"meeting_id",M,"revision_id",B));rows.put("transcript_revision",row("id",B,"meeting_id",M,"kind","WORKING"));rows.put("template_revision",row("id",B));rows.put("exclusion_revision",row("id",B,"meeting_id",M));var proof=new WorkspaceTaskRelations(jdbc,new WorkspaceReadBudget());proof.capture(List.of(task));proof.lockAndCompare();rows.get("transcript_revision").put("kind","RAW");assertThrows(WorkspaceReadBudget.Unavailable.class,()->new WorkspaceTaskRelations(jdbc,new WorkspaceReadBudget()).capture(List.of(task)));rows.get("transcript_revision").put("kind","WORKING");rows.get("exclusion_revision").put("meeting_id",C);assertThrows(WorkspaceReadBudget.Unavailable.class,()->new WorkspaceTaskRelations(jdbc,new WorkspaceReadBudget()).capture(List.of(task)));}
}
